{"command": "Get-Command node, npm, winget -ErrorAction SilentlyContinue | Select-Object Name, Source
Write-Output "--- search python.exe in common roots (depth-limited) ---"
$roots = @("C:\Users\PC\AppData\Local\npm-cache", "C:\Users\PC\.dsh", "C:\Program Files", "C:\Program Files (x86)")
foreach ($r in $roots) {
  if (Test-Path $r) {
    Get-ChildItem -Path $r -Filter "python.exe" -Recurse -Depth 4 -ErrorAction SilentlyContinue | Select-Object -First 10 -ExpandProperty FullName
  }
}", "description": "Look for node, npm, winget and bundled python"}

