content.arguments:
{"command": "$env:PYTHONUTF8="1"
$ws = "G:\※ 2💻 Share\Test\202609200855Start"
$wheels = Join-Path $ws ".wheels"; New-Item -ItemType Directory -Force -Path $wheels | Out-Null
$base = "http://pypi.tuna.tsinghua.edu.cn/simple"
$pkgs = @{
  "idna"="idna-3.10-py3-none-any.whl";
  "xlsxwriter"="XlsxWriter-3.2.9-py3-none-any.whl";
  "python-docx"="python_docx-1.2.0-py3-none-any.whl";
  "tzdata"="tzdata-2026.3-py2.py3-none-any.whl"
}
foreach ($k in $pkgs.Keys) {
  $url = "$base/$k/"
  try {
    $html = (curl.exe -sS --max-time 30 $url)
    $m = [regex]::Matches($html, 'href="([^"]*' + [regex]::Escape($pkgs[$k]) + '[^"]*)"')
    if ($m.Count -gt 0) {
      $href = $m[0].Groups[1].Value
      if ($href -notmatch '^https?://') { $href = "http://pypi.tuna.tsinghua.edu.cn" + $href }
      $out = Join-Path $wheels $pkgs[$k]
      curl.exe -sS --max-time 120 -o $out $href
      Write-Output "$k -> $out ($((Get-Item $out -ErrorAction SilentlyContinue).Length) bytes)"
    } else { Write-Output "$k -> NO MATCH" }
  } catch { Write-Output "$k ERR $($_.Exception.Message)" }
}", "description": "Download wheels directly via HTTP", "timeoutMs": 420000}

