{"file_path": "G:\※ 2💻 Share\Test\202609200855Start\.probe_test.py", "content": "import os, sys, tempfile, json
from pathlib import Path

ws = Path(sys.argv[1]).resolve()
out = {}

try:
    with tempfile.TemporaryDirectory(prefix='.storage-probe-', dir=ws) as folder:
        out['mktempdir'] = True
        root = Path(folder)
        path = root / 'probe.bin'
        try:
            with path.open('xb') as stream:
                stream.write(b'capability'); stream.flush()
                out['write'] = True
                try:
                    os.fsync(stream.fileno()); out['fsync'] = True
                except OSError as e:
                    out['fsync_err'] = f'{type(e).__name__}: {e}'
        except OSError as e:
            out['write_err'] = f'{type(e).__name__}: {e}'
        try:
            os.replace(path, root / 'committed.bin'); out['replace'] = True
        except OSError as e:
            out['replace_err'] = f'{type(e).__name__}: {e}'
except OSError as e:
    out['mktempdir_err'] = f'{type(e).__name__}: {e}'

# dependency metadata visibility
from importlib import metadata
deps = {}
for name in ('idna', 'XlsxWriter', 'python-docx', 'cryptography', 'tzdata'):
    try:
        deps[name] = metadata.version(name)
    except metadata.PackageNotFoundError:
        deps[name] = None
out['deps'] = deps
out['sys_path_head'] = sys.path[:4]
print(json.dumps(out, ensure_ascii=False, indent=1))
"}

