content.arguments:
{"content": "import os, sys, tempfile, json
from pathlib import Path
from importlib import metadata

ws = Path(sys.argv[1]).resolve()
out = {}

# direct metadata probe
out['sys_path'] = sys.path[:5]
for name in ('idna', 'XlsxWriter', 'python-docx', 'cryptography', 'tzdata'):
    try:
        out[f'dep:{name}'] = metadata.version(name)
    except metadata.PackageNotFoundError:
        out[f'dep:{name}'] = 'NOT_FOUND'
    except OSError as e:
        out[f'dep:{name}'] = f'OSError {e}'

for mod in ('idna', 'xlsxwriter', 'docx', 'cryptography', 'tzdata'):
    try:
        __import__(mod)
        out[f'import:{mod}'] = 'OK'
    except Exception as e:
        out[f'import:{mod}'] = f'{type(e).__name__}: {e}'

# storage probe exactly as the skill does it
try:
    with tempfile.TemporaryDirectory(prefix='.storage-probe-', dir=ws) as folder:
        root = Path(folder)
        with (root / 'probe.bin').open('xb') as fh:
            fh.write(b'capability'); fh.flush()
            os.fsync(fh.fileno())
        os.replace(root / 'probe.bin', root / 'committed.bin')
        out['storage_probe'] = 'OK'
except OSError as e:
    out['storage_probe'] = f'{type(e).__name__}: {e}'

print(json.dumps(out, ensure_ascii=False, indent=1))
", "file_path": "G:\※ 2💻 Share\Test\202609200855Start\.probe3.py"}

