content.arguments:
{"content": """"Generate the PAGE_CAPTURE target list and submission envelope.

Source of truth is the run's own discovery facts (`staging/tool-facts/EX-*/search.json`),
read in plan order. URLs are de-duplicated in first-seen order exactly as the
orchestrator's page plan does. No identifier is invented here.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

RUN = Path(__file__).resolve().parent.parent / "runs" / "北京路历史文化街区"


def plan_queries(run: Path) -> list[dict]:
    plans = sorted((run / "staging" / "pipeline" / "operational").glob("plan-*.json"))
    if not plans:
        raise SystemExit("no plan file found")
    plan = json.loads(plans[0].read_text(encoding="utf8"))
    return plan["queries"]


def search_facts(run: Path, execution_id: str) -> dict | None:
    path = run / "staging" / "tool-facts" / execution_id / "search.json"
    if not path.exists():
        return None
    return json.loads(path.read_text(encoding="utf8"))


def build_targets(run: Path) -> list[dict]:
    targets: list[dict] = []
    seen: set[str] = set()
    for query in plan_queries(run):
        execution_id = query["execution_id"]
        fact = search_facts(run, execution_id)
        if not fact:
            continue
        for url in fact.get("urls") or []:
            if not isinstance(url, str) or not url.startswith("http"):
                continue
            if url in seen:
                continue
            seen.add(url)
            targets.append(
                {
                    "execution_id": execution_id,
                    "query_id": query["query_id"],
                    "query": query["query"],
                    "url": url,
                }
            )
    return targets


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run", type=Path, default=RUN)
    parser.add_argument("--mode", choices=("targets", "envelope"), default="targets")
    parser.add_argument("--action-id", default="")
    parser.add_argument("--pages-dir", type=Path)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--max-chars", type=int, default=60000)
    args = parser.parse_args()

    targets = build_targets(args.run)
    if args.mode == "targets":
        args.out.write_text(
            json.dumps([t["url"] for t in targets], ensure_ascii=False, indent=1),
            encoding="utf8",
        )
        print(f"targets={len(targets)} written to {args.out}")
        by_exec: dict[str, int] = {}
        for t in targets:
            by_exec[t["execution_id"]] = by_exec.get(t["execution_id"], 0) + 1
        print(f"distinct execution_ids={len(by_exec)}")
        return 0

    if not args.action_id or not args.pages_dir:
        raise SystemExit("--action-id and --pages-dir required for envelope mode")

    index_path = args.pages_dir / "_index.json"
    index = {}
    if index_path.exists():
        for row in json.loads(index_path.read_text(encoding="utf8")):
            index[row["request_url"]] = row

    records = []
    missing = []
    for target in targets:
        row = index.get(target["url"])
        if not row:
            missing.append(target["url"])
            continue
        payload = json.loads((args.pages_dir / row["file"]).read_text(encoding="utf8"))
        if payload.get("access_status") == "failed":
            records.append(
                {
                    "execution_id": target["execution_id"],
                    "request_url": target["url"],
                    "error_type": payload.get("error_type", "fetch_failed"),
                }
            )
            continue
        body = payload.get("page_body") or ""
        if args.max_chars and len(body) > args.max_chars:
            body = body[: args.max_chars]
        records.append(
            {
                "execution_id": target["execution_id"],
                "request_url": target["url"],
                "final_url": payload.get("final_url") or target["url"],
                "page_title": payload.get("page_title") or "",
                "page_body": body,
                "retrieved_at": payload.get("retrieved_at"),
                "body_format": payload.get("body_format", "text/html"),
                "tool_name": payload.get("tool_name", "host_page_read"),
                "access_status": payload.get("access_status", "full"),
                "actual_fetch_method": payload.get("actual_fetch_method", ""),
            }
        )

    envelope = {"action_id": args.action_id, "records": records}
    args.out.write_text(
        json.dumps(envelope, ensure_ascii=False, indent=1), encoding="utf8"
    )
    print(
        f"records={len(records)} failures={sum(1 for r in records if 'error_type' in r)} "
        f"missing_from_disk={len(missing)}"
    )
    for url in missing[:20]:
        print("  MISSING:", url)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
